// map: key -> shared_ptr<Node>；头尾哨兵节点
// get: 命中则把节点移到最近使用（splice 到头部）
// put: 命中改值并提到头部；未命中新建节点，超容量则 erase 最久节点（map 与链表同步删除，shared_ptr 自动释放）

struct FileDeleter { void operator()(FILE* f) const { if (f) { std::cout << "closed\n"; fclose(f); } } };
std::unique_ptr<FILE, FileDeleter> safe_open(const char* p) {
  return std::unique_ptr<FILE, FileDeleter>(fopen(p, "w"), FileDeleter{});
}
// 调用方：auto f = safe_open("t.txt");  // 独占，不可拷贝，作用域结束自动 closed
